// intent: Verify that parsing pretty-printed JSON with various counts of space indentation works correctly via contiguous span input.
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>

int main() {
    for (int indent = 0; indent <= 33; ++indent) {
        std::string spaces(indent, ' ');
        std::string json_str = "{\n" + spaces + "\"a\": 1\n}";
        try {
            auto j = nlohmann::json::parse(json_str);
            std::cout << indent << ": " << j.dump() << std::endl;
        } catch (const std::exception& e) {
            std::cout << indent << ": EXCEPTION: " << e.what() << std::endl;
        }
    }
    return 0;
}
